# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

OPEN = "09:00-17:00"


def run(worked, opening=OPEN):
    spans = [parse_span(text) for text in worked]
    return find_gaps(spans, parse_span(opening))


class GapTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        found = run(["09:00-12:00", "13:00-17:00"])
        want = ["gap 12:00-13:00 (60 min)"]
        self.assertEqual(found, want)

    def test_edges_and_overlaps(self):
        found = run(["10:00-12:00", "11:00-16:00"])
        self.assertEqual(found, [
            "gap 09:00-10:00 (60 min)",
            "gap 16:00-17:00 (60 min)"
        ])

    def test_full_coverage(self):
        self.assertEqual(run(["09:00-17:00"]), [])

    def test_no_spans(self):
        found = run([])
        want = ["gap 09:00-17:00 (480 min)"]
        self.assertEqual(found, want)

    def test_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            run(["08:00-10:00"])
